-- ===========================================================================
begin;

alter table public.cadre_resultats
  add column if not exists description text,
  add column if not exists groupes_cibles text,
  add column if not exists objectif text,
  add column if not exists justification text,
  add column if not exists hypothese_critique text,
  add column if not exists desagrege_par text,
  add column if not exists elements_calcul text,
  add column if not exists formule_mathematique text,
  add column if not exists niveau_validation text,
  add column if not exists outils_mesure text,
  add column if not exists commentaires text;

delete from public.cadre_resultats;

insert into public.cadre_resultats (
  id, code, libelle_court, nom, composante, sous_composante, est_odp,
  reference_value, unite, frequence, source_donnees, methodologie_collecte, responsable,
  description, groupes_cibles, objectif, justification, hypothese_critique,
  desagrege_par, elements_calcul, formule_mathematique, niveau_validation, outils_mesure, commentaires,
