  realise_2023, realise_2024, realise_2025, realise_2026, realise_2027,
  final_prevu, final_realise
) values
  (1, 'IODP1.1', 'Ventes des petits exploitants', 'Ventes des produits agricoles et alimentaires par les petits exploitants', 'ODP', 'Améliorer l''accès au marché des petits exploitants dans les zones du projet', true, '26', '%', 'Semestrielle / annuelle', 'Enquêtes ménages, données organisations de producteurs, suivi marché', 'Enquête sur la production', 'Opérateur technique pour la collecte', 'Produire davantage sans pouvoir vendre n''améliore pas le revenu des ménages. Cet indicateur est le seul du cadre qui relie la production à un débouché commercial ; il valide ou infirme la théorie du changement du projet sur le volet marché.', 'Petits exploitants agricoles bénéficiaires de l''appui du projet (semences, intrants, formation, équipement)', 'Ameliorer l''accès au marché des petits exploitants agricole dans les zones du projet', 'Permet de mesurer les surplus commercialisé des petits exploitants (agriculteurs, éleveurs et pisciculteurs) appuyés par le Projet.', 'Non adhésion de l''OT ou les petits exploitants eux mêmes.', 'Tous (hommes et femmes),Femmes (adultes et jeunes),Jeunes (hommes et femmes) de 18-35ans par opposition aux adultes', 'Soustraire la Qté vendues de l''année en cours de la Qté de l''année precedente, diviser la difference par la Qté de l''année precedente', '((Qn-Qn-1)/Qn-1)*100', 'Province ,National', 'Questionnaire de production sur KoboToolbox', 'CONTRÔLE QUALITÉ / VALIDATION (Étude de référence IDEA 2026, Tableau 19 — Commercialisation et accès au marché) : Contrôle par culture, territoire, volumes déclarés et débouchés disponibles', 0, 5, 10, 20, 30, null, 39, 29, 70, null, 30, null),
  (2, 'IODP2.1.1', 'Adoption de technologies améliorées', 'Agriculteurs adoptent une technologie améliorée', 'ODP', 'Augmenter la productivité agricole des petits exploitants agricoles dans les zones du projet', true, '0', 'Nombre', 'Campagne agricole / vague de suivi', 'Enquêtes ménages, suivi opérateurs techniques', 'Visite de suivi des PEA', 'Opérateur technique pour la collecte', 'La distribution d''intrants ou la formation ne garantit pas l''adoption. Cet indicateur mesure le passage de l''offre à l''usage, étape sans laquelle les gains de rendement attendus ne se matérialisent pas.', 'Petits exploitants agricoles ayant reçu un appui du projet et mettant effectivement en œuvre au moins une technologie agricole améliorée sur leur exploitation.', 'Agmenter la productivité agricole des petits exploitants agricoles', 'Permet de mesurer le nombre de petits exploitants ayant adoptés une technologies ameliorés promue par le programme', 'Non adhesion des petits exploitants', 'Province/Territoire/Genre', 'Dénombrement des PEA ayant adoptés les technologies améliorées', 'Somme des exploitants adoptants, cumulée depuis le démarrage du projet', 'UPE/UNCP', 'Formulaire de suivi d''adoption sur KoboToolbox', 'DONNÉES DÉSAGRÉGÉES PAR SEXE — Agriculteurs adoptent une technologie améliorée — Femmes : Valeur de référence = 0 ; Cibles annuelles 2024=10000, 2025=50000, 2026=100000, 2027=150000. || CONTRÔLE QUALITÉ / VALIDATION (Étude de référence IDEA 2026, Tableau 19 — Adoption des technologies promues) : Vérification des définitions, cohérence avec les appuis effectivement distribués', 0, 20000, 100000, 200000, 300000, null, 9160, 36026, null, null, 300000, 0),
  (3, 'IODP2.1.2', 'Adoption de technologies améliorées — Femmes', 'Agriculteurs adptent une technologie améliorée (femmes)', 'ODP', 'Augmenter la productivité agricole des petits exploitants agricoles dans les zones du projet', true, '0', 'Nombre', 'Campagne agricole / vague de suivi', 'Enquêtes ménages, suivi opérateurs techniques', 'Visite de suivi des PEA', 'Opérateur technique pour la collecte', 'Les femmes assurent une part majoritaire du travail agricole en RDC mais accèdent moins aux intrants et aux formations. Suivre séparément leur taux d''adoption permet de détecter un décrochage et d''ajuster le ciblage en cours de projet.', 'Petits exploitants agricoles ayant reçu un appui du projet et mettant effectivement en œuvre au moins une technologie agricole améliorée sur leur exploitation.', 'Agmenter la productivité agricole des petits exploitants agricoles', 'Permet de mesurer le nombre de petits exploitants ayant adoptés une technologies ameliorés promue par le programme', 'Non adhesion des petits exploitants', 'Province/Territoire/Genre', 'Dénombrement des PEA ayant adoptés les technologies améliorées', 'Somme des exploitants adoptants, cumulée depuis le démarrage du projet', 'UPE/UNCP', 'Formulaire de suivi d''adoption sur KoboToolbox', 'DONNÉES DÉSAGRÉGÉES PAR SEXE — Agriculteurs adoptent une technologie améliorée — Femmes : Valeur de référence = 0 ; Cibles annuelles 2024=10000, 2025=50000, 2026=100000, 2027=150000. || CONTRÔLE QUALITÉ / VALIDATION (Étude de référence IDEA 2026, Tableau 19 — Adoption des technologies promues) : Vérification des définitions, cohérence avec les appuis effectivement distribués', 0, 10000, 50000, 100000, 150000, null, 5527, 22697, null, null, 150000, 0),
  (4, 'IODP2.3', 'Rendement du maïs (pratiques AIC)', 'Rendement des maïs à travers l''incorporation des pratiques/technologies intelligentes face au climat', 'ODP', 'Augmenter la productivité agricole des petits exploitants agricoles dans les zones du projet', true, '0.5', '%', 'Campagne agricole / vague de suivi', 'Enquêtes ménages, suivi opérateurs techniques', 'Visite de suivi des PEA', 'Opérateur technique pour la collecte', 'C''est l''indicateur qui teste la promesse centrale du projet sur la productivité. Un gain nul ou faible signalerait un paquet technique inadapté ou une mise en œuvre incomplète, et justifierait sa révision.', 'Les petits exploitants agricoles', 'Augmenter la productivité agricoles des petits exploitants agricoles dans les zones du projet', 'Permet de mesurer en pourcentage le rendement de maïs grâce à l''incorporation des pratiques/technologies intelligentes face au climat.', 'Non adoption des technolgies agricoles améliorées par les petits exploitants', 'Province/Territoire', 'Différence entre le rendement de l''année de réf et celui après l''incorporation des pratiques, permettant de calculer l''augmentation en pourcentage du rendement de maïs.', '((Rendement année visée - Rendement année de réf.) / Rendement année de réf.) x 100)', 'Province', 'Formulaire de suivi d''adoption sur KoboToolbox', 'CONTRÔLE QUALITÉ / VALIDATION (Étude de référence IDEA 2026, Tableau 19 — Rendements par culture) : Contrôle des superficies plantées/récoltées, volumes récoltés, nombre de prélèvements pour les cultures à récolte progressive, densité de plantation et valeurs aberrantes', 0, 30, 60, 80, 100, null, 20, 50, 0, null, 100, null),
  (5, 'IODP2.4', 'Rendement du manioc (pratiques AIC)', 'Rendement de manioc à travers l''incorporation des pratiques/technologies intelligentes face au climat', 'ODP', 'Augmenter la productivité agricole des petits exploitants agricoles dans les zones du projet', true, '0', '%', 'Vague d''enquête / campagne agricole', 'Enquêtes ménages, dispositifs de suivi agricole', 'Enquête sur la production des agriculteurs subventionnés', 'UPEP, services agricoles, équipes S&E', 'Le manioc constitue la base de la sécurité alimentaire dans les provinces couvertes. Un gain de rendement y a un effet direct sur la disponibilité alimentaire des ménages, au-delà du seul revenu.', 'Les petits exploitants agricoles', 'Augmenter la productivité agricoles des petits exploitants agricole dans les zones du projet', 'Permet de mesurer le rendement de manioc grace à l''incorporation des pratiques/technologies intelligents face au climat .', 'Non adoption des technolgies agricoles améliorées par les petits exploitants', 'Province/Territoire', null, '((Rendement année visée - Rendement année de réf.) / Rendement année de réf.) x 100)', 'Province', 'Fiche', 'CONTRÔLE QUALITÉ / VALIDATION (Étude de référence IDEA 2026, Tableau 19 — Rendements par culture) : Contrôle des superficies plantées/récoltées, volumes récoltés, nombre de prélèvements pour les cultures à récolte progressive, densité de plantation et valeurs aberrantes', 0, 0, 25, 40, 50, null, 0, null, 0, null, 50, null),
  (6, 'IODP2.5', 'Mortalité animale (réduction)', 'Taux de mortalité animale', 'ODP', 'Augmenter la productivité agricole des petits exploitants agricoles dans les zones du projet', true, '0', '%', 'Après événement / semestrielle', 'Enquêtes ménages, reporting d''urgence, dispositifs locaux', 'Enquête sur les bénéficiaires', 'UPEP, UNCP, acteurs locaux', 'La mortalité du petit élevage est la première cause de décapitalisation des ménages ruraux. La réduire protège l''épargne des ménages plus sûrement qu''une augmentation de la production.', 'Petits éleveurs bénéficiaires du projet détenant des caprins ou de la volaille dans les provinces couvertes.', 'Mesurer la réduction effective des pertes animales chez les éleveurs appuyés, qui traduit l''efficacité combinée de la vaccination, de la prophylaxie et des conseils zootechniques diffusés.', 'Permet de mesurer la reduction du taux de mortalité animale grâce aux campagnes de vaccination prévues.', 'Non adoption des campagnes de vaccination par les petits exploitants agricoles (éleveurs)', 'Province/Territoire', 'Nombre total des bêtes, Nombre total des décès', '(Nombre des décès / nombre total des bêtes) x 100', 'Province', 'Fiche', 'CONTRÔLE QUALITÉ / VALIDATION (Étude de référence IDEA 2026, Tableau 19 — Réponse aux chocs et assistance reçue) : Vérification du type de choc, délai d''assistance, couverture et bénéficiaires servis', 0, 20, 30, 40, 50, null, 0, null, null, null, 50, null),
  (7, 'IODP3.1', 'Plans de contingence approuvés', 'Plan de contingence pour le risque lié au secteur agricole', 'ODP', 'Renforcer la capacité du secteur public dans la réponse aux urgences agricoles éligibles', true, '0', 'Nombre', 'Après événement / semestrielle', 'Actes d''approbation des plans de contingence ; rapports d''activité du programme ; archives du Secrétariat Général à l''Agriculture.', 'Recensement documentaire auprès des services concernés, avec collecte de la copie de l''acte d''approbation comme pièce justificative obligatoire.', 'UNCP', 'La Composante 4 du projet prévoit un mécanisme d''intervention d''urgence. Sans plan de contingence approuvé en amont, ce mécanisme ne peut être activé dans les délais utiles.', 'Les petits exploitants agricoles', 'Augmenter la productivité agricoles des petits exploitants agricole dans les zones du projet', 'Permet de mesurer l''augmentation du nombre de plans de contingence approuvés pour la réponse aux urgences liées au secteur agricole (y compris le COVID 19) .', 'Non implication des services publics de l''Etat.', 'N/A', 'Dénombrement', 'Cumul', 'National', 'Fiche de recensement documentaire', 'CONTRÔLE QUALITÉ / VALIDATION (Étude de référence IDEA 2026, Tableau 19 — Réponse aux chocs et assistance reçue) : Vérification du type de choc, délai d''assistance, couverture et bénéficiaires servis', 2, 2, 2, 5, 5, 1, null, null, null, null, 5, 0),
  (8, 'IR1.1.1.1', 'Agriculteurs atteints (actifs ou services)', 'Agriculteurs atteints par des actifs ou des services agricoles', 'Composante 1', 'Sous-composante 1.1 : Appui aux petits exploitants', false, '0', 'Nombre', 'Trimestrielle / semestrielle', 'Enquêtes ménages, données des services publics agricoles', 'Données collectées par l''OT pour les agriculteurs ayant reçu au moins la première partie de leur subenventions', 'UPEP, services techniques provinciaux', 'C''est l''indicateur de portée du projet, exigé au titre des indicateurs institutionnels de la Banque Mondiale. Il constitue le dénominateur naturel des taux d''adoption et de satisfaction mesurés par ailleurs.', 'Les petits exploitants agricoles', 'Augmenter la productivité agricoles des petits exploitants agricoles dans les zones du projet', 'Permet de mesurer le nombre des petits exploitants ayant bénéficié d''actifs ou services agricoles (les cultures, le bétail, etc) grâce à l''appui du programme', 'Non adhésion des petits exploitants agricoles', 'Povince/Territoire', 'Dénombrement', 'Cumul', 'Province', 'Fiche', 'DONNÉES DÉSAGRÉGÉES PAR SEXE — Agriculteurs atteints par des actifs ou des services agricoles — Femmes : Valeur de référence = n.d. ; Cibles annuelles 2024=10000, 2025=50000, 2026=100000, 2027=150000. || CONTRÔLE QUALITÉ / VALIDATION (Étude de référence IDEA 2026, Tableau 19 — Accès aux services agricoles) : Croisement entre déclarations des ménages et registres de services fournis', 0, 20000, 100000, 200000, 300000, null, 9160, 36026, null, null, 300000, 63186),
  (9, 'IR1.1.1.2', 'Agriculteurs atteints — Femmes', 'Agriculteurs atteints par des actifs ou des services agricoles (femmes)', 'Composante 1', 'Sous-composante 1.1 : Appui aux petits exploitants', false, '0', 'Nombre', 'Trimestrielle / semestrielle', 'Enquêtes ménages, données des services publics agricoles', 'Données collectées par l''OT pour les agriculteurs ayant reçu au moins la première partie de leur subenventions', 'UPEP, services techniques provinciaux', 'L''égalité d''accès aux actifs productifs est un engagement du projet vis-à-vis du bailleur. Un suivi séparé permet de corriger le ciblage en cours d''exécution plutôt qu''au moment du bilan.', 'Les petits exploitants agricoles', 'Augmenter la productivité agricoles des petits exploitants agricoles dans les zones du projet', 'Permet de mesurer le nombre des petits exploitants ayant bénéficié d''actifs ou services agricoles (les cultures, le bétail, etc) grâce à l''appui du programme', 'Non adhésion des petits exploitants agricoles', 'Povince/Territoire', 'Dénombrement', 'Cumul', 'Province', 'Fiche', 'DONNÉES DÉSAGRÉGÉES PAR SEXE — Agriculteurs atteints par des actifs ou des services agricoles — Femmes : Valeur de référence = n.d. ; Cibles annuelles 2024=10000, 2025=50000, 2026=100000, 2027=150000. || CONTRÔLE QUALITÉ / VALIDATION (Étude de référence IDEA 2026, Tableau 19 — Accès aux services agricoles) : Croisement entre déclarations des ménages et registres de services fournis', 0, 20000, 100000, 200000, 300000, null, 5527, 22697, null, null, 300000, 37224),
  (10, 'IR1.1.2', 'Fournisseurs d’intrants proposant l’AIC/AIN', 'Fournisseurs d''intrants et de services agricoles offrant des technologies AIC ou AIN', 'Composante 1', 'Sous-composante 1.1 : Appui aux petits exploitants', false, '4', 'Nombre', 'À chaque campagne', 'Bases opérateurs, RNA, suivi UPEP', 'Données collectées par l’OT sur les prestataires privés d''intrants et services qui sont sur le registre de subvention du PNDA', 'Opérateurs techniques, DANTIC, UPEP', 'L''appui direct du projet cessera à sa clôture. Si aucun fournisseur privé ne propose ces technologies, l''adoption retombera. Cet indicateur mesure la construction du marché, pas la distribution gratuite.', 'Les fournisseurs d''intrants', 'Augmenter la productivité agricoles des petits exploitants agricoles dans les zones du projet', 'Permet de mesurer le nombre des fournisseurs d''intrants et prestataires du secteur privé offrant des technologies AIC et AIN dans la zone du projet', 'Non adhésion des fournisseurs aux technologies AIC et AIN', 'Province/Territoire', 'Dénombrement', 'Total', 'Province', 'Fiche', 'CONTRÔLE QUALITÉ / VALIDATION (Étude de référence IDEA 2026, Tableau 19 — Distribution et utilisation des paquets techniques) : Concordance entre bénéficiaires enregistrés, cartes, distributions, utilisation effective et traçabilité dans le RNA / bases de suivi', 4, 8, 10, 15, 20, 4, 16, 29, null, null, 25, 69),
  (11, 'IR1.1.3.1', 'Exploitants inscrits au RNA', 'Petits exploitants agricoles inscrits au registre national d''agriculteurs (RNA)', 'Composante 1', 'Sous-composante 1.1 : Appui aux petits exploitants', false, '0', 'Nombre', 'Avant chaque vague de suivi ou d''évaluation', 'RNA, bases opérateurs techniques, listes UPEP, validations communautaires, données GPS', 'Données collectées dans le Système d''information sur les bénéficiaires', 'UNCP, DANTIC, UPEP, opérateurs techniques', 'Sans registre, aucun appui ne peut être ciblé, tracé ni audité, et le double comptage est inévitable. Le RNA est l''infrastructure d''information sur laquelle repose la crédibilité de tout le dispositif.', 'Les petits exploitants agricoles', 'Augmenter la productivité agricole des petits exploitants agricole dans les zones du projet', 'Permet de mesurer le nombre des petits exploitants (agriculteurs, éleveurs et pisciculteurs) enregistrés dans le RNA', 'Non opérationnalisation du RNA', 'Province/Territoire', 'Dénombrement', 'Cumul/Total', 'Province/National', 'Fiche', 'DONNÉES DÉSAGRÉGÉES PAR SEXE — Petits exploitants enregistrés dans le RNA — Femmes : Valeur de référence = n.d. ; Cibles annuelles 2024=10000, 2025=50000, 2026=100000, 2027=150000. || CONTRÔLE QUALITÉ / VALIDATION (Étude de référence IDEA 2026, Tableau 19 — Base de sondage et identification des PEA) : Nettoyage des doublons, vérification des identifiants RNA, contrôle des localisations, validation des statuts bénéficiaires/témoins, traçabilité des remplacements et archivage de la version utilisée', 0, 20000, 100000, 200000, 300000, 0, 9675, 65615, null, null, 300000, 93290),
  (12, 'IR1.1.3.2', 'Exploitants inscrits au RNA — Femmes', 'Petits exploitants agricoles inscrits au registre national d''agriculteurs (RNA) (femmes)', 'Composante 1', 'Sous-composante 1.1 : Appui aux petits exploitants', false, '', 'Nombre', 'Avant chaque vague de suivi ou d''évaluation', 'RNA, bases opérateurs techniques, listes UPEP, validations communautaires, données GPS', 'Données collectées dans le Système d''information sur les bénéficiaires', 'UNCP, DANTIC, UPEP, opérateurs techniques', 'L''inscription nominative au RNA conditionne l''accès individuel aux appuis, au crédit et à l''assurance. Un déficit d''enregistrement des femmes se traduirait mécaniquement par un déficit d''accès à tout le reste.', 'Les petits exploitants agricoles', 'Augmenter la productivité agricole des petits exploitants agricole dans les zones du projet', 'Permet de mesurer le nombre des petits exploitants (agriculteurs, éleveurs et pisciculteurs) enregistrés dans le RNA', 'Non opérationnalisation du RNA', 'Province/Territoire', 'Dénombrement', 'Cumul/Total', 'Province/National', 'Fiche', 'DONNÉES DÉSAGRÉGÉES PAR SEXE — Petits exploitants enregistrés dans le RNA — Femmes : Valeur de référence = n.d. ; Cibles annuelles 2024=10000, 2025=50000, 2026=100000, 2027=150000. || CONTRÔLE QUALITÉ / VALIDATION (Étude de référence IDEA 2026, Tableau 19 — Base de sondage et identification des PEA) : Nettoyage des doublons, vérification des identifiants RNA, contrôle des localisations, validation des statuts bénéficiaires/témoins, traçabilité des remplacements et archivage de la version utilisée', 0, 20000, 100000, 200000, 300000, 0, 5620, 40026, null, null, 300000, 54646),
  (13, 'IR1.1.4', 'Superficie sous pratiques AIC', 'Superficie sous pratiques agricoles intelligentes face au climat dans les provinces ciblées (hectare)', 'Composante 1', 'Sous-composante 1.1 : Appui aux petits exploitants', false, '0', 'Ha', 'Vague d''enquête / campagne agricole', 'Relevés parcellaires géoréférencés rattachés au Registre National des Agriculteurs ; bases des opérateurs techniques.', 'Relevé GPS du contour de la parcelle lors de la visite de suivi, calcul automatique de la superficie, et rattachement à l''identifiant RNA de l''exploitant.', 'Opérateur technique pour le relevé ; UPE pour la supervision ; UNCP / Unité S&E pour le calcul et le contrôle de vraisemblance.', 'L''effet climatique et agronomique du projet dépend des hectares transformés, pas des personnes touchées. Un exploitant peut adopter une pratique sur une petite parcelle seulement ; seule la superficie le révèle.', 'Parcelles exploitées par les bénéficiaires du projet sur lesquelles au moins une pratique agricole intelligente face au climat est effectivement mise en œuvre.', 'Mesurer l''emprise physique réelle des pratiques climato-intelligentes, c''est-à-dire la surface de terre effectivement gérée autrement, et non le nombre d''exploitants formés.', 'L''effet climatique et agronomique du projet dépend des hectares transformés, pas des personnes touchées. Un exploitant peut adopter une pratique sur une petite parcelle seulement ; seule la superficie le révèle.', 'Les parcelles concernées sont identifiables et mesurables sur le terrain, et les exploitants acceptent le relevé GPS de leurs limites parcellaires.', 'Province ; territoire ; sexe de l''exploitant ; type de pratique AIC ; filière ; statut foncier.', 'Somme des superficies des parcelles portant le marqueur « pratique AIC », mesurées au GPS. En l''absence de relevé GPS, superficie déclarée par l''exploitant, explicitement étiquetée comme estimation.', 'Somme des superficies mesurées, en hectares, cumulée depuis le démarrage du projet. FORMULE PROVISOIRE ACTUELLEMENT APPLIQUÉE : IR1.1.1 × 0,5 — voir rubrique 14.', 'UPE : contrôle des relevés GPS et de la cohérence des polygones. UNCP / Unité S&E : contrôle de vraisemblance des superficies moyennes par exploitant. Responsable National S&E : validation officielle.', 'GPS de terrain ou application mobile de relevé parcellaire avec calcul de surface, intégrée au formulaire de suivi KoboToolbox.', 'INDICATEUR ACTUELLEMENT CALCULÉ, NON MESURÉ. Sur 2024 comme sur 2025, la superficie déclarée vaut exactement la moitié du nombre d''agriculteurs atteints : 4 580 pour 9 160, puis 18 013 pour 36 026. La valeur découle d''une hypothèse implicite de 0,5 hectare par exploitant, non d''un relevé de terrain. L''indicateur ne peut donc jamais contredire celui dont il dérive, et toute variation réelle de la taille des parcelles reste invisible. RÈGLE DE TRANSITION PROPOSÉE : conserver la valeur calculée en la signalant explicitement comme estimation tant que la couverture GPS des parcelles reste inférieure à 60 %, puis basculer sur la mesure réelle. Les deux séries doivent coexister une campagne complète afin de mesurer l''écart entre l''hypothèse et la réalité.', 0, 10000, 50000, 100000, 150000, 0, 4580, 18013, null, null, 150000, 31593),
  (14, 'IR1.1.5', 'Paquets techniques AIC/AIN proposés', 'Paquets techniques AIC/AIN proposés dans la zone du projet', 'Composante 1', 'Sous-composante 1.1 : Appui aux petits exploitants', false, '0', 'Nombre', 'À chaque campagne', 'Bases des opérateurs techniques, RNA, rapports de diffusion des technologies, fiches de suivi UPEP et rapports S&E.', 'Revue documentaire et enregistrement des paquets techniques proposés par les opérateurs techniques, avec vérification par les équipes S&E.', 'Opérateurs techniques, UPEP, DANTIC et cellule S&E/UNCP.', 'On ne peut demander à un exploitant d''adopter une technologie qui n''a pas été formalisée, testée et documentée. Cet indicateur mesure la disponibilité de l''offre, en amont de tous les indicateurs d''adoption.', 'Petits exploitants agricoles, opérateurs techniques et structures d''appui mettant en œuvre les paquets techniques AIC/AIN.', 'Augmenter la productivité agricole des petits exploitants agricoles grâce à la diffusion de paquets techniques adaptés à l''AIC et à l''AIN.', 'Permet de mesurer le nombre de paquets techniques AIC/AIN effectivement proposés et disponibles pour les exploitants dans les zones du projet.', 'Disponibilité des technologies et intrants nécessaires et adhésion des opérateurs techniques et des petits exploitants à leur diffusion et à leur adoption.', 'Province/Territoire/Culture ou spéculation/Type de paquet technique.', 'Dénombrement des paquets techniques AIC/AIN distincts, validés et proposés aux bénéficiaires au cours de la période.', 'Somme des paquets techniques validés et diffusables, cumulée depuis le démarrage du projet.', 'Province / UNCP.', 'Fiche de suivi des paquets techniques, base de données S&E/RNA et rapport des opérateurs techniques.', 'Contrôle qualité : vérifier que chaque paquet technique est documenté, validé, non dupliqué et effectivement proposé dans une année d''intervention. Assurer...', null, null, null, null, null, null, null, null, null, null, 4, 0),
